import csv

# Read races.csv to get raceId -> round mapping
races = {}
with open('csv/races.csv', 'r') as f:
    reader = csv.reader(f)
    header = next(reader)
    for row in reader:
        raceId, year, round_num, circuitId, name, date, time, url = row
        races[raceId] = {
            'round': int(round_num),
            'name': name,
            'year': year
        }

# Read driverStandings.csv and filter for Alex Yoong (driverId 62)
yoong_entries = []
with open('csv/driverStandings.csv', 'r') as f:
    reader = csv.reader(f)
    header = next(reader)
    for row in reader:
        driverStandingsId, raceId, driverId, points, position, positionText, wins = row
        if driverId == '62':
            yoong_entries.append({
                'raceId': raceId,
                'points': points,
                'position': position,
                'positionText': positionText,
                'wins': wins
            })

# Find entries where round < 20
results = []
for entry in yoong_entries:
    raceId = entry['raceId']
    if raceId in races:
        round_num = races[raceId]['round']
        if round_num < 20:
            results.append({
                'raceId': raceId,
                'round': round_num,
                'race_name': races[raceId]['name'],
                'year': races[raceId]['year'],
                'position': entry['position']
            })

print("Alex Yoong races with round < 20:")
for r in results:
    print(r)

